# 1. The KPI table: each value with its comparisons
def show(name, value):
    if name in ("Website conversion", "Return rate"):
        return f"{value:.2%}"
    return f"£{value:,.2f}" if name == "Average order value" else (f"£{value:,.0f}" if name == "Revenue" else f"{value:,.0f}")


def change(name, a, b):
    if name in ("Website conversion", "Return rate"):
        return f"{(a - b) * 100:+.2f} pts"
    return f"{a / b - 1:+.1%}"


print(f"{'KPI':20}{'Dec 2025':>12}{'vs Nov 2025':>14}{'vs Dec 2024':>14}")
for name in now:
    print(f"{name:20}{show(name, now[name]):>12}{change(name, now[name], last_month[name]):>14}"
          f"{change(name, now[name], last_year[name]):>14}")
print(f"Revenue against target: £{now['Revenue']:,.0f} of £{target:,.0f} ({now['Revenue'] / target:.1%})")
